function hasAuthenticatedSession(){return Boolean(authUser)}
async function authRequest(action,data){const res=await fetch('/api/auth/'+action,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await res.json();if(!res.ok){const error=new Error(uiText(result.error||'연결에 실패했어요.'));error.status=res.status;throw error;}return result}
function updateAccountHeader(){refreshAccountSaved();const b=document.querySelector('#account-session-button')||document.querySelector('.account button[data-info="로그인"]');if(!b)return;b.id='account-session-button';b.removeAttribute('data-info');let wrap=b.closest('.account-profile-menu');if(!wrap){wrap=document.createElement('div');wrap.className='account-profile-menu';b.before(wrap);wrap.append(b);}wrap.querySelector('.account-profile-popover')?.remove();b.innerHTML=authUser?`<span class="header-profile-avatar" aria-hidden="true">${esc(Array.from(authUser.name||authUser.email||'?')[0].toUpperCase())}</span><span>${esc(authUser.name)} ▾</span>`:'로그인 ↗';if(!authUser)uiMessage(b,'로그인 ↗');else b.removeAttribute('data-i18n');b.setAttribute('aria-expanded','false');b.onclick=()=>{if(!authUser){go('login');return}const open=wrap.classList.toggle('is-open');b.setAttribute('aria-expanded',String(open))};if(!authUser){wrap.classList.remove('is-open');const wallet=document.querySelector('.account .wallet');if(wallet){wallet.innerHTML='<span>✦</span> NEON';wallet.setAttribute('data-i18n-aria-label','NEON 지갑');wallet.setAttribute('aria-label',uiText('NEON 지갑'));}return;}b.setAttribute('aria-haspopup','true');const pop=document.createElement('div');pop.className='account-profile-popover';pop.id='account-profile-popover';b.setAttribute('aria-controls',pop.id);pop.innerHTML=`<a class="account-profile-summary" href="#/creator-profile"><span class="account-profile-avatar">${esc(authUser.name.slice(0,1))}</span><span><strong class="account-profile-name">${esc(authUser.name)}</strong><small>${esc(authUser.plan||'Free')} Plan · <span data-i18n="내 프로필 ↗">내 프로필 ↗</span></small></span></a><a class="account-neon-status" href="#/wallet"><span><span data-i18n="✦ NEON 잔액">✦ NEON 잔액</span></span><strong>${Number.isSafeInteger(authUser.neonBalance)?authUser.neonBalance.toLocaleString('ko-KR'):'확인 중'} <small>NEON ↗</small></strong></a><a href="#/creator-plan"><span data-i18n="내 요금제">내 요금제 </span><strong class="account-plan-badge">${esc(authUser.plan||'Free')}</strong></a><a href="#/orders" data-i18n="구매 주문 내역 ↗">구매 주문 내역 ↗</a><a href="#/creator-dashboard" data-i18n="크리에이터 대시보드 ↗">크리에이터 대시보드 ↗</a><a href="#/creator-profile" data-i18n="프로필 수정 ↗">프로필 수정 ↗</a><a href="#/recent-assets" data-i18n="최근 본 에셋">최근 본 에셋</a><a href="#/email-settings" data-i18n="선택형 이메일 알림">선택형 이메일 알림</a><a href="#/account-withdrawal" data-i18n="회원 탈퇴">회원 탈퇴</a><a href="#/connections" data-i18n="로그인 계정 연결 ↗">로그인 계정 연결 ↗</a>${authUser.isAdmin?'<a href="#/admin-dashboard" data-i18n="관리자 대시보드">관리자 대시보드</a><a href="#/admin-reviews" data-i18n="관리자 에셋 심사 ↗">관리자 에셋 심사 ↗</a>':''}<button type="button" class="account-sign-out" data-i18n="로그아웃">로그아웃</button>`;wrap.append(pop);pop.querySelectorAll('a').forEach(a=>a.onclick=()=>{wrap.classList.remove('is-open');b.setAttribute('aria-expanded','false');b.blur()});pop.querySelector('button').onclick=async()=>{try{await authRequest('logout',{});authUser=null;updateAccountHeader();route()}catch(e){toast(e.message)}};wrap.onkeydown=e=>{if(e.key==='Escape'){wrap.classList.remove('is-open');b.focus({preventScroll:true});b.setAttribute('aria-expanded','false')}};refreshHeaderNeon();const owner=authUser.id;authRequest('creator-profile').then(({profile})=>{if(authUser?.id!==owner||!profile||!pop.isConnected)return;const displayName=profile.displayName||authUser.name||authUser.email||'?';const initial=Array.from(displayName.trim())[0]?.toUpperCase()||'?';b.querySelector('.header-profile-avatar').nextElementSibling.textContent=displayName+' ▾';b.querySelector('.header-profile-avatar').textContent=initial;pop.querySelector('.account-profile-name').textContent=displayName;pop.querySelector('.account-profile-avatar').textContent=initial;if(profile.avatarVersion){b.querySelector('.header-profile-avatar').innerHTML=`<img src="/api/auth/creator/avatar?v=${encodeURIComponent(profile.avatarVersion)}" alt="">`;}if(profile.avatarVersion)pop.querySelector('.account-profile-avatar').innerHTML=`<img src="/api/auth/creator/avatar?v=${encodeURIComponent(profile.avatarVersion)}" alt="${esc(uiText('프로필 사진'))}">`;}).catch(()=>{});}
let headerNeonRefreshVersion=0;
async function refreshHeaderNeon(){
 const version=++headerNeonRefreshVersion,owner=authUser?.id;if(!owner)return;
 try{const wallet=await authRequest('neon/status');if(version!==headerNeonRefreshVersion||authUser?.id!==owner)return;
 const amount=wallet.mode==='test'?wallet.testBalance:authUser.neonBalance;
 const label=wallet.mode==='test'?'테스트 NEON':'NEON';
 const button=document.querySelector('.account .wallet');if(button){button.innerHTML=`<span>✦</span> ${Number(amount).toLocaleString('ko-KR')} NEON${wallet.mode==='test'?'<small class="header-neon-test">TEST</small>':''}`;button.setAttribute('aria-label',`${label} 잔액 ${amount}, 지갑 열기`);button.setAttribute('data-i18n-aria-label',`${label} 잔액 ${amount}, 지갑 열기`);}
 const status=document.querySelector('.account-neon-status');if(status)status.innerHTML=`<span data-i18n="${wallet.mode==='test'?'✦ 테스트 NEON 잔액':'✦ NEON 잔액'}">${wallet.mode==='test'?'✦ 테스트 NEON 잔액':'✦ NEON 잔액'}</span><strong>${Number(amount).toLocaleString('ko-KR')} <small>NEON ↗</small></strong>`;
 }catch{}
}
