function renderMailToken(mode,token){
 document.title=(mode==='VERIFY'?'이메일 인증':'비밀번호 재설정')+' — NovaNoxX';
 history.replaceState(null,'','#/'+(mode==='VERIFY'?'verify-email':'reset-password'));
 page.innerHTML=pageHeading('ACCOUNT',mode==='VERIFY'?'이메일 주소를 확인해주세요.':'새 비밀번호를 입력해주세요.','아래 버튼을 누르면 요청을 완료합니다.')+'<form id="mail-token-form" class="page-panel narrow"><p id="mail-token-status" role="status" aria-live="polite"></p>'+(mode==='RESET'?'<label data-i18n="새 비밀번호">새 비밀번호<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label data-i18n="새 비밀번호 확인">새 비밀번호 확인<input name="confirm" type="password" autocomplete="new-password" required></label>':'')+'<button type="submit" class="primary">'+(mode==='VERIFY'?'이메일 인증 완료':'비밀번호 변경')+'</button><p><a href="#/login" data-i18n="로그인하기">로그인하기</a> · <a href="#/reset-password" data-i18n="새 재설정 메일 요청">새 재설정 메일 요청</a></p></form>';
 const form=page.querySelector('#mail-token-form'),status=page.querySelector('#mail-token-status');
 const owner=authUser?.id,isCurrent=()=>form.isConnected&&page.querySelector('#mail-token-form')===form&&authUser?.id===owner;
 if(!/^[A-Za-z0-9_-]{43}$/.test(token)){status.textContent='유효한 링크가 없습니다. 새 메일을 요청해주세요.';form.querySelector('button').disabled=true;return;}
 form.onsubmit=async e=>{e.preventDefault();if(!isCurrent()||form.querySelector('button').disabled)return;if(mode==='RESET'&&form.elements.password.value!==form.elements.confirm.value){uiMessage(status,"비밀번호 확인이 일치하지 않습니다.");return;}const button=form.querySelector('button');button.disabled=true;try{await authRequest(mode==='VERIFY'?'verify-email':'reset-password',{token,password:form.elements.password?.value});if(!isCurrent())return;form.reset();if(mode==='RESET'){authUser=null;updateAccountHeader();}status.textContent=mode==='VERIFY'?'이메일 인증을 완료했습니다. 이제 로그인해주세요.':'비밀번호를 변경하고 기존 로그인 세션을 해제했습니다. 다시 로그인해주세요.';}catch(error){if(isCurrent()){status.textContent=error.message;button.disabled=false;}}};
}
